def is_closed(R, N):
    R_set = set(R)
    for x in R:
        if 2*x <= N and 2*x not in R_set:
            return False
    for x in R:
        for y in R:
            if x + y <= N and x + y not in R_set:
                return False
    return True

def sum_R(R):
    return sum(R)

